&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;4+ years of operational and/or selling experience in endpoint operations or security&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;2+ years of experience in customer-facing or customer support positions&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Significant software pre-sales or related value-based technical selling&amp;nbsp;expertise&amp;nbsp;in&amp;nbsp;very large&amp;nbsp;enterprise environments&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Experience presenting at multiple levels, from&amp;nbsp;VP level&amp;nbsp;to Solution Users&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;A demonstrated&amp;nbsp;track record&amp;nbsp;of taking ownership of complex initiatives and producing successful outcomes&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Broad knowledge of the IT security, operations, and compliance space and products&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Deep knowledge with hands-on experience in one or more of the following:&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Endpoint Security&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;IT Operations Management&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Regulatory Compliance&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Broad knowledge of scripting languages is a plus&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Demonstrated critical thinking skills&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Excellent written and verbal communication skills&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Naturally team-oriented with a mission-first attitude&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233279&amp;quot;:true,&amp;quot;134245417&amp;quot;:false,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:0}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;BS degree in Computer Science, Mathematics,&amp;nbsp;Engineering&amp;nbsp;or equivalent experience&amp;nbsp;required&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;About Tanium&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;div&gt;Tanium is the Autonomous IT company. Driven by AI and real-time endpoint intelligence, Tanium Autonomous IT empowers IT and security teams to make their organizations unstoppable.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Many of the world’s leading organizations trust Tanium’s single, unified platform for endpoint management and security to innovate faster, stay resilient and move business forward with confidence, at scale. To learn how Tanium delivers Autonomous IT for unstoppable business – visit &lt;u&gt;&lt;a id=&quot;OWA8cd82040-d6a4-2e07-8c22-f773746075e4&quot; href=&quot;http://www.tanium.com/&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;0&quot;&gt;www.tanium.com&lt;/a&gt;&lt;/u&gt; and&amp;nbsp;follow us on &lt;u&gt;&lt;a id=&quot;OWA51246dd5-7f28-280e-6637-139dda4774bb&quot; href=&quot;https://www.linkedin.com/company/tanium&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;1&quot;&gt;LinkedIn&lt;/a&gt;&lt;/u&gt; and &lt;u&gt;&lt;a id=&quot;OWAd79eefc3-ede9-5e26-14d4-517b82af2392&quot; href=&quot;https://twitter.com/Tanium&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-linkindex=&quot;2&quot;&gt;X&lt;/a&gt;&lt;/u&gt;.&lt;/div&gt;
&lt;p&gt;&lt;strong&gt;On a mission. Together.&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Tanium, we are stewards of a culture that emphasizes the importance of collaboration, respect, and diversity. In our pursuit of revolutionizing the way some of the largest enterprises and governments in the world solve their most difficult IT challenges, we are strengthened by our unique perspectives and by our collective actions.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559738&amp;quot;:200,&amp;quot;335559739&amp;quot;:200,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;As a global organization with stakeholders around the world, it’s imperative that the diversity of our customers and communities is reflected internally in our team members. We strive to create a diverse and inclusive environment where everyone feels they have opportunities to succeed and grow because we know that only together can we do great things. &amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our commitment to excellence and innovation has earned us a place on the Forbes Cloud 100 list for ten consecutive years, and we continue to be recognized worldwide as a great place to work.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Each of our team members has 5 days set aside as volunteer time off (VTO) to contribute to the communities they live in and give back to the causes they care about most.&amp;nbsp;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What you’ll get&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;The annual base salary range for this full-time position is C$115,000 to C$176,000&amp;nbsp; and this position will also be commission eligible. This range is an estimate for what Tanium will pay a new hire. The actual annual base salary offered may be adjusted based on a variety of factors, including but not limited to, location, education, skills, training, and experience.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;In addition to an annual base salary, team members will receive equity awards and a generous benefits package consisting of medical, dental and vision plan, family planning benefits, health savings account, flexible spending account, transportation savings account, 401(k) retirement savings plan with company match, life, accident and disability coverage, business travel accident insurance, employee assistance programs, disability insurance, and other well-being benefits.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;Tanium is an Equal Opportunity and Affirmative Action employer. All qualified applicants will receive consideration for employment without regard to race, color, religion, sex, national origin, age, gender identity, sexual orientation, disability, protected Veteran status, or other legally protected categories. If you require a reasonable accommodation in searching for a job opening, completing an application, interviewing, or completing any pre-employment testing or requirements, please contact&amp;nbsp;&lt;a href=&quot;mailto:accommodations@tanium.com&quot;&gt;accommodations@tanium.com&lt;/a&gt;. For more information refer to the “Know Your Rights” poster which is available here -&amp;nbsp;&lt;a href=&quot;https://www.eeoc.gov/poster&quot; target=&quot;_blank&quot;&gt;https://www.eeoc.gov/poster&lt;/a&gt;.&lt;/p&gt;
&lt;p&gt;Please be aware of job offers coming from people claiming to be Tanium employees. Tanium employees will only use @tanium.com email addresses to communicate with you, will have video interviews with you, and will never ask you for money.&lt;/p&gt;
&lt;p&gt;&lt;a href=&quot;https://www.cigna.com/legal/compliance/machine-readable-files&quot; target=&quot;_blank&quot;&gt;This link&lt;/a&gt; leads to the machine readable files that are made available in response to the federal Transparency in Coverage Rule and includes negotiated service rates and out-of-network allowed amounts between health plans and healthcare providers. The machine-readable files are formatted to allow researchers, regulators, and application developers to more easily access and analyze data.&lt;/p&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559685&amp;quot;:1440,&amp;quot;335559740&amp;quot;:240}&quot;&gt;For more information on how Tanium processes your personal data, please see our&amp;nbsp;&lt;a href=&quot;https://www.tanium.com/privacy-policy/&quot; target=&quot;_blank&quot; data-auth=&quot;NotApplicable&quot; data-safelink=&quot;true&quot; data-linkindex=&quot;0&quot;&gt;Privacy Policy&lt;/a&gt;.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;

a16z-temporal-technologies:greenhouse:50.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;About Us&lt;/strong&gt;&lt;/h3&gt;
&lt;div&gt;Temporal is an open source programming model that can simplify code, make applications more reliable, and help developers focus on the important things like delivering features faster. We are on a mission to be the reliable foundation of every developer’s toolbox, and are building the team that will make that happen.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Our values guide us —they are present in how we show up, make decisions, and work together to make an impact. We’re curious, driven, collaborative, genuine and humble.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Temporal is growing and we are looking for those who share our values, challenge &#39;standard&#39; thinking, and want to influence our future. If you have a passion for improving the developer experience, building world-class open-source software and communities, and want to be a part of our amazing team, we&#39;d love to hear from you!&lt;/div&gt;&lt;/div&gt;&lt;div&gt;
&lt;h3&gt;&lt;strong&gt;Summary&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Temporal is shaping the future of application development by enabling organizations to build, scale, and run resilient applications. We are seeking a highly skilled and experienced&amp;nbsp;&lt;strong&gt;Strategic Account Executive based in Germany &lt;/strong&gt;to join our &lt;strong&gt;New Logo team&lt;/strong&gt; and drive revenue within some of the largest and most complex enterprise organizations.&lt;/p&gt;
&lt;p&gt;In this role, you will own the DACH (Germany, Austria and Switzerland) sales territory, navigating matrixed enterprise companies and selling to highly technical personas such as software engineers, engineering leaders, and architects. As a strategic partner to our customers, you will bring a proven ability to lead sophisticated sales processes, uncover opportunities within massive organizations, and drive adoption of Temporal’s solutions. Your entrepreneurial mindset will help you thrive in a high-growth, startup environment, while your expertise in scaling revenue within complex organizations will make you an invaluable asset to our team.&lt;/p&gt;
&lt;p&gt;Come work with some of the brightest minds in the tech industry and help transform how modern applications are built. You will contribute to the growth of a category-defining company at the forefront of innovation.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;What You&#39;ll Do&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Own and manage the entire sales cycle, from prospecting to close, with a focus on growing revenue with new enterprise customers&lt;/li&gt;
&lt;li&gt;Develop and execute strategic sales plans to break into large, matrixed enterprise accounts&lt;/li&gt;
&lt;li&gt;Engage with software engineers, architects, and technical stakeholders to understand their needs and position Temporal effectively across a wide range of use cases&lt;/li&gt;
&lt;li&gt;Navigate complex technical discussions and align Temporal’s capabilities with customer priorities&lt;/li&gt;
&lt;li&gt;Build and nurture quality relationships with prospects, acting as a trusted advisor throughout the sales process&lt;/li&gt;
&lt;li&gt;Partner with customer success, solutions architecture, and product teams to ensure a seamless customer experience&lt;/li&gt;
&lt;li&gt;Leverage your expertise in enterprise sales to identify and capture high-value opportunities within large, complex organizations, driving net-new customer acquisition&lt;/li&gt;
&lt;li&gt;Innovate and adapt sales strategies to meet the dynamic needs of enterprise businesses in a rapidly evolving market&lt;/li&gt;
&lt;li&gt;Be based in Germany with the ability to travel throughout the country for in-person meetings&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What You&#39;ll Bring&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Demonstrated expertise in enterprise software sales, typically gained through 7+ years of experience in similar roles&lt;/li&gt;
&lt;li&gt;Proven track record of selling to software engineers, technical decision-makers, and engineering leaders&lt;/li&gt;
&lt;li&gt;Navigate complex technical discussions and collaboratively align Temporal’s capabilities with customer priorities&lt;/li&gt;
&lt;li&gt;Demonstrated success navigating and closing deals within large, matrixed enterprise organizations&lt;/li&gt;
&lt;li&gt;Experience driving high-growth sales motions within enterprise accounts, identifying opportunities, and scaling revenue&lt;/li&gt;
&lt;li&gt;Comfortable operating in a fast-paced, high-growth environment with a hands-on approach and entrepreneurial mindset&lt;/li&gt;
&lt;li&gt;Exceptional relationship management skills, with the ability to influence and build trust across multiple levels of an organization&lt;/li&gt;
&lt;li&gt;Demonstrated success in consistently achieving or surpassing revenue goals&lt;/li&gt;
&lt;li&gt;Experience working with cutting-edge developer tools or infrastructure products&lt;/li&gt;
&lt;li&gt;Experience working with OSS, and monetizing OSS&lt;/li&gt;
&lt;li&gt;Familiarity with consumption-based sales models and driving adoption of technical products&lt;/li&gt;
&lt;li&gt;Outstanding communication and negotiation skills, with the ability to present to technical and executive audiences&lt;/li&gt;
&lt;li&gt;A passion for technology and a deep curiosity for solving complex customer challenges&lt;/li&gt;
&lt;li style=&quot;font-weight: bold;&quot;&gt;&lt;strong&gt;German language proficiency is a requirement for success in this role.&lt;/strong&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Compensation&lt;/strong&gt;&lt;/h3&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;The estimated pay range for this role is an OTE of €250,000 (50/50 split)&lt;/li&gt;
&lt;li&gt;This role is eligible to participate in Temporal&#39;s equity plan&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;div&gt;&lt;em&gt;Compensation ranges reflect salary and commission compensation (when applicable) across several geographic markets. Employment offers carefully consider multiple factors, including prior experience, knowledge, expertise, skillset, market location, and job level assessed during the interview process.&lt;/em&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;Employee benefits and perks below are for full-time employees, part-time or temporary positions are excluded.&amp;nbsp;&lt;/em&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;
&lt;div&gt;&lt;strong&gt;U.S. Benefits&amp;nbsp;&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;Unlimited PTO, 12 Holidays + 2 Floating Holidays&lt;/li&gt;
&lt;li&gt;100% Premiums Coverage for Medical, Dental, and Vision&lt;/li&gt;
&lt;li&gt;AD&amp;amp;D, LT &amp;amp; ST Disability, and Life Insurance (Standard &amp;amp; Supplemental Available)&lt;/li&gt;
&lt;li&gt;Empower 401K Plan&lt;/li&gt;
&lt;li&gt;Additional Perks for Learning &amp;amp; Development, Lifestyle Spending, In-Home Office Setup, Professional Memberships, WFH Meals, Internet Stipend and more!&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div&gt;
&lt;div&gt;&lt;strong&gt;International Benefits&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;
&lt;p&gt;Paid Time Off (PTO) and Benefits outside the United States vary by country, and are issued in partnership with &lt;a class=&quot;postings-link&quot; href=&quot;http://remote.com/&quot;&gt;Remote.com&lt;/a&gt;.&amp;nbsp; Additionally, Temporal offers perks to all international employees for learning &amp;amp; career development, a lifestyle spending account, in-home office setup (in addition to company-issued hardware), professional memberships, work-from-home meals, and access to the Calm app for mental wellness.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Travel&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Temporal is a globally distributed, collaborative team that values opportunities for in-person connection. Occasional travel may be required for company events, team offsites, and other meaningful moments that bring us together.&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;div&gt;&lt;strong&gt;Additional Perks&amp;nbsp;&lt;/strong&gt;&lt;/div&gt;
&lt;div&gt;
&lt;ul&gt;
&lt;li&gt;$3,600 / Year Work from Home Meals&amp;nbsp;&lt;/li&gt;
&lt;li&gt;$1,800 / Year Professional Enrichment (Career Development &amp;amp; Professional Memberships)&lt;/li&gt;
&lt;li&gt;$1,200 / Year Lifestyle Spending Account&lt;/li&gt;
&lt;li&gt;$1,000 / Year In-Home Office Setup (In addition to Temporal issued equipment - laptop, monitor, keyboard, mouse, trackpad, and extension power cable at no cost to you)&lt;/li&gt;
&lt;li&gt;$74 / Month Reimbursement for Internet&lt;/li&gt;
&lt;li&gt;Calm App Subscription for Mental Health &amp;amp; Wellness&lt;/li&gt;
&lt;/ul&gt;
&lt;/div&gt;
&lt;div&gt;&lt;em&gt;Temporal Technologies is an Equal Opportunity Employer. Temporal Technologies does not discriminate on the basis of race, religion, color, sex, gender identity, sexual orientation, age, non-disqualifying physical or mental disability, national origin, veteran status, or any other basis covered by appropriate law. All employment is decided on the basis of qualifications, merit, and business need. We embrace and celebrate differences and diversity.&lt;/em&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;Temporal is committed to providing access, equal opportunity, and reasonable accommodation for individuals with disabilities in employment, its services, programs, and activities. If you need to request a reasonable accommodation, please let your Recruiter know so we can assist.&lt;/em&gt;&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;&lt;em&gt;We are not working with external recruitment agencies, thanks.&lt;/em&gt;&lt;/div&gt;&lt;/div&gt;

a16z-waymo:greenhouse:7461103.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;Waymo is an autonomous driving technology company with the mission to be the world&#39;s most trusted driver. Since its start as the Google Self-Driving Car Project in 2009, Waymo has focused on building the Waymo Driver—The World&#39;s Most Experienced Driver™—to improve access to mobility while saving thousands of lives now lost to traffic crashes. The Waymo Driver powers Waymo’s fully autonomous ride-hail service and can also be applied to a range of vehicle platforms and product use cases. The Waymo Driver has provided over ten million rider-only trips, enabled by its experience autonomously driving over 100 million miles on public roads and tens of billions in simulation across 15+ U.S. states.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;The Onboard Infrastructure Team is responsible for designing and developing the core infrastructure for Autonomous Driving Vehicle (ADV) systems, which includes perception, planning, and routing functionalities. This encompasses defining the architecture and frameworks used to implement these critical systems. Furthermore, the team manages the entire runtime environment for both on-car systems and large-scale simulation, focusing on end-to-end performance, reliability, and developer experience throughout the development lifecycle. This is a hybrid position reporting to a Staff Engineer, Tech Lead Manager.&lt;/p&gt;
&lt;p&gt;&lt;em&gt;In this hybrid role, you will report to a Staff Software Engineer / TLM.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You will:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Drive architectural and framework improvements to boost driving quality, performance, reliability, and enhance the overall developer experience.&lt;/li&gt;
&lt;li&gt;Gain a holistic understanding of the entire Waymo code lifecycle—from deployment on autonomous vehicles to running large-scale simulations—to ensure the highest quality across all operational environments.&lt;/li&gt;
&lt;li&gt;Architect, implement, and deploy essential C++ APIs responsible for critical functions such as asynchrony management, experimentation pipelines, multi-platform deployments, complex data extraction, debug tooling, and advanced system visualization.&lt;/li&gt;
&lt;li&gt;Act as a crucial resource for onboard teams, guiding them in setting up software for maximum efficiency, flexibility, scalability, and reliability, ensuring it meets Waymo&#39;s rapidly evolving needs.&lt;/li&gt;
&lt;li&gt;Significantly improve our internal tools, infrastructure, and development processes to accelerate engineering velocity while maintaining tight control over system complexity, performance, reliability, and developer experience.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;You have:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;BS/MS in Comp Sci, EE, Robotics, Physics, Math, or related field (or equivalent experience)&lt;/li&gt;
&lt;li&gt;5 years of experience as a software engineer or similar roles&lt;/li&gt;
&lt;li&gt;3 years of experience in C++&lt;/li&gt;
&lt;li&gt;2 year of experience in software infrastructure/systems&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;We prefer:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;3 years of experience working on a large-scale, high-complexity system (supporting hundreds of engineers)&lt;/li&gt;
&lt;li&gt;Experience in performance analysis, including profiling, benchmarking, and optimization&lt;/li&gt;
&lt;li&gt;Experience in improving software reliability and executing root cause analysis within complex software environments&lt;/li&gt;
&lt;li&gt;Experience developing evaluation systems and metrics&lt;/li&gt;
&lt;li&gt;Experience building tools to enhance the developer experience&lt;/li&gt;
&lt;li&gt;Experience in robotics&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-Hybrid&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;The expected base salary range for this full-time position across US locations is listed below. Actual starting pay will be based on job-related factors, including exact work location, experience, relevant training and education, and skill level. Your recruiter can share more about the specific salary range for the role location or, if the role can be performed remote, the specific salary range for your preferred location, during the hiring process.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Waymo employees are also eligible to participate in Waymo’s discretionary annual bonus program, equity incentive plan, and generous Company benefits program, subject to eligibility requirements.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;Salary Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$213,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$263,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

a16z-xai:greenhouse:5090189007.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;&lt;strong&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;ABOUT xAI&lt;/span&gt;&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;xAI’s mission is to create AI systems that can accurately understand the universe and aid humanity in its pursuit of knowledge. &lt;/span&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;Our team is small, highly motivated, and focused on engineering excellence. This organization is for individuals who appreciate challenging themselves and thrive on curiosity. &lt;/span&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;We operate with a flat organizational structure. All employees are expected to be hands-on and to contribute directly to the company’s mission. Leadership is given to those who show initiative and consistently deliver excellence. Work ethic and strong prioritization skills are important. &lt;/span&gt;&lt;span style=&quot;font-family: arial, helvetica, sans-serif;&quot;&gt;All employees are expected to have strong communication skills. They should be able to concisely and accurately share knowledge with their teammates.&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;ABOUT THE ROLE:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;As an AI Tutor specialized in multilingual audio capabilities, you will contribute to xAI&#39;s mission by training and refining Grok to excel in voice interactions, speech recognition, and auditory experiences across diverse languages, accents, and cultural contexts. Your work will focus on curating and annotating high-quality audio data to enhance Grok&#39;s global accessibility, enabling natural spoken interactions for users worldwide, bridging language barriers through accurate speech processing, and improving the AI&#39;s handling of multilingual audio nuances.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;RESPONSIBILITIES:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Use proprietary software to provide labels, annotations, recordings, and inputs on projects involving multilingual audio clips, voice recordings, speech samples, and auditory elements in various languages.&lt;/li&gt;
&lt;li&gt;Support the delivery of high-quality curated audio data that ensures clear, natural spoken output, accurate representation of linguistic and prosodic details (such as intonation, rhythm, and accent), and professional audio standards.&lt;/li&gt;
&lt;li&gt;Collaborate with technical staff to develop tasks that improve AI&#39;s ability to handle speech modulation, accent variation, noise in real-world recordings, and multilingual audio processing.&lt;/li&gt;
&lt;li&gt;Work with technical staff to improve annotation tools for efficient audio workflows.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;BASIC QUALIFICATIONS:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Native proficiency in&lt;strong&gt; Danish&lt;/strong&gt;&amp;nbsp;with exposure to diverse accents, dialects, or regional variations.&lt;/li&gt;
&lt;li&gt;Proficiency in English (minimum B2 level) with clear, natural vocal delivery and pronunciation suitable for audio recording purposes.&lt;/li&gt;
&lt;li&gt;Strong auditory perception to identify nuances in speech, accents, pronunciation, intonation, and audio quality across languages.&lt;/li&gt;
&lt;li&gt;Demonstrated ability to handle multilingual audio content, including evaluating speech accuracy, cultural vocal expressions, and contextual interpretation in spoken form.&lt;/li&gt;
&lt;li&gt;Demonstrated ability to transcribe audio with high accuracy across accents and varying audio quality.&lt;/li&gt;
&lt;li&gt;Comfort providing high-quality voice recordings and feedback on audio samples in multiple languages.&lt;/li&gt;
&lt;li&gt;Strong comprehension skills and the ability to make independent judgments on ambiguous or varied audio material, including noisy or accented speech.&lt;/li&gt;
&lt;li&gt;Strong communication, interpersonal, analytical, detail-oriented, and organizational skills, with the ability to articulate audio-related feedback effectively.&lt;/li&gt;
&lt;li&gt;Commitment to developing AI that masters sophisticated multilingual audio capabilities.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;PREFERRED SKILLS AND EXPERIENCE:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Demonstration of exceptional attention to linguistic nuance, auditory detail, and data quality beyond standard transcription work.&lt;/li&gt;
&lt;li&gt;Deep understanding and taste of what good/useful Audio data is.&lt;/li&gt;
&lt;li&gt;Strong command of advanced transcription and annotation practices, including handling disfluencies, accents, and prosodic features (intonation, stress, rhythm, emotion, etc) with high consistency and accuracy.&lt;/li&gt;
&lt;li&gt;Background in linguistics (e.g., phonetics, phonology, sociolinguistics), speech sciences, cognitive science, or a related field, or equivalent practical experience, with demonstrated ability to analyze accent variation, pronunciation differences, and multilingual speech patterns.&lt;/li&gt;
&lt;li&gt;Experience working with speech/audio datasets, annotation workflows, or AI training data, including knowledge/experience with training voice models, and an understanding of how data quality impacts model performance.&lt;/li&gt;
&lt;li&gt;Professional experience in voice work, including voice acting, voice recording, podcasting with a measurable audience (e.g., X following), or similar audio production demonstrating attention to clarity and recording quality.&lt;/li&gt;
&lt;li&gt;Demonstrated ability to exercise independent judgment in ambiguous audio scenarios and make consistent, defensible annotation decisions.&lt;/li&gt;
&lt;li&gt;Portfolio (strongly preferred for advanced candidates): Voice samples, annotated transcripts, or audio-related work demonstrating quality, methodology, and attention to detail.&lt;/li&gt;
&lt;li&gt;Candidates with professional experience in voice, linguistics, speech data, or speech evaluation and research are especially encouraged to apply.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;LOCATION AND OTHER EXPECTATIONS:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Tutor roles may be offered as full-time, part-time, or contractor positions, depending on role needs and candidate fit.&lt;/li&gt;
&lt;li&gt;For contractor positions, hours will vary widely based on project scope and contractor availability, with no fixed commitments required. On average, most projects may require at least 10 hours per week to deliver effectively, though this is not a fixed commitment and depends on the scope of work. Contractors have full flexibility to set their own hours and determine the exact amount of time needed to complete deliverables.&lt;/li&gt;
&lt;li&gt;Tutor roles may be performed remotely from any location worldwide, subject to legal eligibility, time-zone compatibility, and role-specific needs.&lt;/li&gt;
&lt;li&gt;For US-based candidates, please note that we are unable to hire in Wyoming and Illinois at this time.&lt;/li&gt;
&lt;li&gt;We are unable to provide visa sponsorship.&lt;/li&gt;
&lt;li&gt;For those who will be working from a personal device, your computer must be a Chromebook, a Mac with macOS 11.0 or later, or Windows 10 or later.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;COMPENSATION AND BENEFITS:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;US-based candidates: $35/hour - $45/hour&lt;strong&gt;&amp;nbsp;&lt;/strong&gt;depending on factors including relevant experience, skills, education, geographic location, and qualifications. International candidates: Information will be provided to you during the recruitment process.&lt;/p&gt;
&lt;p&gt;Benefits vary based on employment type, location, and jurisdiction. Benefits for eligible U.S.-based positions include health insurance, 401(k) plan, and paid sick leave. Specific details and role-specific information will be provided to you during the interview process.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;em&gt;xAI is an equal opportunity employer. For details on data processing, view our&amp;nbsp;&lt;/em&gt;&lt;em&gt;&lt;a href=&quot;https://x.ai/legal/recruitment-privacy-notice&quot; target=&quot;_blank&quot;&gt;Recruitment Privacy Notice&lt;/a&gt;.&lt;/em&gt;&lt;/p&gt;&lt;/div&gt;

a16z-zipline:greenhouse:7656397003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Zipline&lt;/h3&gt;
&lt;p&gt;Zipline is the world’s largest and most experienced drone delivery service. We are on a mission to serve all humans equally by ensuring access to food, medicine and essential goods anytime, anywhere. We design, build, and operate the world’s largest autonomous logistics system, delivering critical supplies quickly and reliably. Today, Zipline operates on four continents, makes a delivery somewhere in the world every 30 seconds, and has completed millions of deliveries to date, including blood, vaccines, medical supplies, food, and retail products.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our customers include the world’s largest and most prominent healthcare systems, governments, retailers, restaurants and global businesses who rely on us to save lives, reduce emissions, increase economic opportunity, and provide delivery from point A to point B as fast as possible. The drone is only 15% of what we’ve built to enable seamless, reliable, global operations.&lt;/p&gt;
&lt;p&gt;Our system strengthens supply chains, reduces congestion, and gives people time back. With more than 140 million commercial autonomous miles safely flown, Zipline is redefining access to healthcare, consumer products, and food across the globe.&lt;/p&gt;
&lt;p&gt;We operate at a global scale and are looking for practical problem solvers who thrive on real-world challenges and rapid growth. Our team is motivated by building systems that have a direct, meaningful impact on people’s lives and by scaling the future of logistics. We are seeking people who sculpt from first principles, enjoy facing adversity, and can do the impossible at record breaking speeds.&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;About You and The Role&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;Zipline operates a large-scale autonomous system that depends on reliable, low latency communication between vehicles, ground infrastructure, and cloud services. Our Cloud Communications team owns the platform that moves critical data from embedded systems into the cloud and ensures that data is reliable, scalable, and observable.&lt;/p&gt;
&lt;p&gt;We are looking for a Senior or Staff Software Engineer to expand and harden this platform. This role focuses on connecting hardware assets to the cloud, hosting and orchestrating new data use cases, and building distributed observability that spans embedded software, cellular networks, and cloud microservices.&lt;/p&gt;
&lt;p&gt;You will work closely with Embedded and Autonomy teams who design software to get data off devices. Your responsibility is to ensure that data is securely ingested into the cloud, deduplicated, stored, processed, monitored, and made available for both real time and offline workflows.&lt;/p&gt;
&lt;p&gt;This is a high ownership role with direct impact on flight reliability, operational visibility, and the scalability of our global network.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;What You’ll Do&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Own and evolve the services that connect vehicles, charging and loading stations, fulfillment hardware, and other field deployed infrastructure to the cloud&lt;/li&gt;
&lt;li&gt;Design and maintain asset-to-cloud APIs, message schemas, and communication clients in partnership with embedded teams&lt;/li&gt;
&lt;li&gt;Build and operate ingestion pipelines for new data streams, including high volume perception and telemetry data generated by vehicles and ground systems&lt;/li&gt;
&lt;li&gt;Design systems for deduplication, validation, and scalable storage of high volume telemetry and event data&lt;/li&gt;
&lt;li&gt;Ensure secure provisioning of hardware assets, including certificate management and integration with internal provisioning systems&lt;/li&gt;
&lt;li&gt;Expand cross-stack telemetry to measure latency and uptime across embedded systems, cellular networks, and cloud infrastructure&lt;/li&gt;
&lt;li&gt;Build correlation systems that link events in vehicle software to cloud-side signals such as service errors or streaming backlogs&lt;/li&gt;
&lt;li&gt;Develop tooling and dashboards that allow engineering and operations teams to monitor the health of device-to-cloud interactions and track reliability trends&lt;/li&gt;
&lt;li&gt;Improve correctness, testability, and auditability of distributed systems that operate in safety critical contexts&lt;/li&gt;
&lt;li&gt;Contribute across the stack as needed, from backend services and infrastructure to internal tooling&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Basic Qualifications&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;5+ years of experience building and operating reliable distributed systems&lt;/li&gt;
&lt;li&gt;Experience designing APIs and data models for high volume or real time systems&lt;/li&gt;
&lt;li&gt;Experience with cloud infrastructure such as AWS and container orchestration platforms such as Kubernetes&lt;/li&gt;
&lt;li&gt;Experience building or operating streaming and messaging systems&lt;/li&gt;
&lt;li&gt;Strong fundamentals in networking, security, and systems design&lt;/li&gt;
&lt;li&gt;Track record of owning problems end to end, from design through production operation&lt;/li&gt;
&lt;li&gt;Clear and concise communication skills and comfort working across hardware, embedded, and cloud teams&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Preferred Qualifications&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience working on systems that interface with hardware or embedded devices&lt;/li&gt;
&lt;li&gt;Experience building observability platforms, telemetry pipelines, or reliability tooling&lt;/li&gt;
&lt;li&gt;Experience with certificate based authentication and secure device provisioning&lt;/li&gt;
&lt;li&gt;Experience debugging complex, cross system failures that span client, network, and server layers&lt;/li&gt;
&lt;li&gt;Experience in safety critical or high reliability domains&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What Else You Need to Know&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;The starting cash range for this role is $180,000 - 250,000. Please note that this is a target starting cash range for a candidate who meets the minimum qualifications for this role. The final cash pay will depend on a variety of factors, including a specific candidate’s experience, qualifications, skills, working location, and projected impact. The total compensation package may also include equity compensation, discretionary bonuses, benefits such as medical, dental and vision insurance, paid time off, and more.&lt;/p&gt;
&lt;p&gt;Zipline is an equal opportunity employer and prohibits discrimination and harassment of any type without regard to race, color, ancestry, national origin, religion, disability, medical condition, genetic information, sex, sexual orientation, gender identity, age, marital status, military or veteran status, citizenship, or other characteristics protected by law.&lt;/p&gt;
&lt;p&gt;We value diversity at Zipline and welcome applications from those who are traditionally underrepresented in tech. If you are excited about the role but unsure whether you meet every qualification, we encourage you to apply.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Please Note&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We have received reports stating that certain individuals are reaching out under false pretenses, claiming to be Zipline employees or representatives. They may seek to gain access to your personal information or to acquire money by offering fictitious employment opportunities.&lt;/p&gt;
&lt;p&gt;Genuine Zipline employees or representatives will never ask you for money or payment in exchange for employment opportunities or related services. Any such offer that claims to be from us is deceitful and part of a fraud.&lt;/p&gt;
&lt;p&gt;If you believe you have been targeted by a fraudulent party, please contact us at security@flyzipline.com upon receiving a suspicious offer or claim.&lt;/p&gt;

a16z-zipline:greenhouse:7747477003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Zipline&lt;/h3&gt;
&lt;p&gt;Zipline is the world’s largest and most experienced drone delivery service. We are on a mission to serve all humans equally by ensuring access to food, medicine and essential goods anytime, anywhere. We design, build, and operate the world’s largest autonomous logistics system, delivering critical supplies quickly and reliably. Today, Zipline operates on four continents, makes a delivery somewhere in the world every 30 seconds, and has completed millions of deliveries to date, including blood, vaccines, medical supplies, food, and retail products.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our customers include the world’s largest and most prominent healthcare systems, governments, retailers, restaurants and global businesses who rely on us to save lives, reduce emissions, increase economic opportunity, and provide delivery from point A to point B as fast as possible. The drone is only 15% of what we’ve built to enable seamless, reliable, global operations.&lt;/p&gt;
&lt;p&gt;Our system strengthens supply chains, reduces congestion, and gives people time back. With more than 140 million commercial autonomous miles safely flown, Zipline is redefining access to healthcare, consumer products, and food across the globe.&lt;/p&gt;
&lt;p&gt;We operate at a global scale and are looking for practical problem solvers who thrive on real-world challenges and rapid growth. Our team is motivated by building systems that have a direct, meaningful impact on people’s lives and by scaling the future of logistics. We are seeking people who sculpt from first principles, enjoy facing adversity, and can do the impossible at record breaking speeds.&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;What You’ll Do&lt;/h3&gt;
&lt;p&gt;You’ll own high-impact software across one or more parts of Zipline’s application platform, such as:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Partner, merchant, and internal operations tools that help teams run the business day to day&lt;/li&gt;
&lt;li&gt;Marketplace, fulfillment, billing, and support systems that connect demand, delivery, and financial correctness&lt;/li&gt;
&lt;li&gt;Network operations software for simulation, real-time visibility, intervention, orchestration, maintenance, and asset health&lt;/li&gt;
&lt;li&gt;Enterprise systems that power manufacturing, supply chain, inventory, traceability, finance, quality, and field operations&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;You’ll work closely with the people who use these systems every day, from operators and field teams to manufacturing, supply chain, finance, commercial, product, and partner teams. You’ll identify ambiguous problems, design durable systems, build production software end to end, and drive adoption.&lt;/p&gt;
&lt;h3&gt;Why This Role Is Unique&lt;/h3&gt;
&lt;p&gt;This team builds the software backbone of Zipline’s autonomous logistics network, turning complex real-world operations into reliable systems that scale.&lt;/p&gt;
&lt;p&gt;You’ll solve problems like:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;How do we give operators and partners real-time visibility into a complex physical network?&lt;/li&gt;
&lt;li&gt;How do we keep the network moving when demand shifts, weather changes, assets degrade, or capacity gets tight?&lt;/li&gt;
&lt;li&gt;How do we build financial and operational systems where every transaction, part, order, and aircraft state is traceable?&lt;/li&gt;
&lt;li&gt;How do we automate workflows across manufacturing, supply chain, fulfillment, and field operations without losing correctness?&lt;/li&gt;
&lt;li&gt;How do we design software that scales across countries, metros, verticals, and millions of deliveries?&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;These are production systems with immediate operational and business consequences. You’ll have real ownership, make technical and product decisions, and help shape how Zipline scales.&lt;/p&gt;
&lt;h3&gt;What We’re Looking For&lt;/h3&gt;
&lt;p&gt;You may be a strong fit if you:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Have experience building and shipping production software systems&lt;/li&gt;
&lt;li&gt;Bring strong full-stack fundamentals across frontend, backend, services, and data&lt;/li&gt;
&lt;li&gt;Can turn ambiguous, high-stakes problems into simple, reliable software&lt;/li&gt;
&lt;li&gt;Combine product instinct with systems judgment&lt;/li&gt;
&lt;li&gt;Care deeply about reliability, correctness, usability, and operational trust&lt;/li&gt;
&lt;li&gt;Enjoy working directly with users and stakeholders to understand real workflows&lt;/li&gt;
&lt;li&gt;Want to shape architecture and product direction, not just implement scoped features&lt;/li&gt;
&lt;li&gt;Are excited to use modern AI tooling to increase velocity while maintaining strong engineering rigor&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Our current stack includes Go, Python, React, gRPC, Kafka, PostgreSQL, AWS, Bazel, Grafana, and Honeycomb, but we care more about your ability to learn quickly and solve the right problems than your experience with any specific tool.&lt;/p&gt;
&lt;div&gt;
&lt;div&gt;
&lt;div&gt;
&lt;h3&gt;What Else You Need to Know&amp;nbsp; &amp;nbsp;&lt;/h3&gt;
&lt;div&gt;
&lt;div&gt;The starting cash range for this role is $200,000 - $270,000. Please note that this is a target, starting cash range for a candidate who meets the minimum qualifications for this role. The final cash pay for this role will depend on a variety of factors, including a specific candidate&#39;s experience, qualifications, skills, working location, and projected impact. The total compensation package for this role may also include: equity compensation; overtime pay; discretionary annual or performance bonuses; sales incentives; benefits such as medical, dental and vision insurance; paid time off; and more.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;Zipline is an equal opportunity employer and prohibits discrimination and harassment of any type without regard to&amp;nbsp;race, color, ancestry, national origin, religion or religious creed, mental or physical disability, medical condition, genetic information, sex (including pregnancy, childbirth, and related medical conditions), sexual orientation, gender identity, gender expression, age, marital status, military or veteran status, citizenship, or other characteristics protected by state, federal or local law or our other policies.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We value diversity at Zipline and welcome applications from those who are traditionally underrepresented in tech. If you like the sound of this position but are not sure if you are the perfect fit, please apply!&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

a16z-zipline:greenhouse:7768289003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Zipline&lt;/h3&gt;
&lt;p&gt;Zipline is the world’s largest and most experienced drone delivery service. We are on a mission to serve all humans equally by ensuring access to food, medicine and essential goods anytime, anywhere. We design, build, and operate the world’s largest autonomous logistics system, delivering critical supplies quickly and reliably. Today, Zipline operates on four continents, makes a delivery somewhere in the world every 30 seconds, and has completed millions of deliveries to date, including blood, vaccines, medical supplies, food, and retail products.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our customers include the world’s largest and most prominent healthcare systems, governments, retailers, restaurants and global businesses who rely on us to save lives, reduce emissions, increase economic opportunity, and provide delivery from point A to point B as fast as possible. The drone is only 15% of what we’ve built to enable seamless, reliable, global operations.&lt;/p&gt;
&lt;p&gt;Our system strengthens supply chains, reduces congestion, and gives people time back. With more than 140 million commercial autonomous miles safely flown, Zipline is redefining access to healthcare, consumer products, and food across the globe.&lt;/p&gt;
&lt;p&gt;We operate at a global scale and are looking for practical problem solvers who thrive on real-world challenges and rapid growth. Our team is motivated by building systems that have a direct, meaningful impact on people’s lives and by scaling the future of logistics. We are seeking people who sculpt from first principles, enjoy facing adversity, and can do the impossible at record breaking speeds.&lt;/p&gt;&lt;/div&gt;&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;h3&gt;&lt;strong&gt;About You and The Role&amp;nbsp;&amp;nbsp;&lt;/strong&gt;&lt;/h3&gt;
&lt;div&gt;
&lt;p&gt;As a Site Acquisition Associate, you are responsible for creating opportunities that fuel our network expansion. You are a relentless prospector who enjoys the hunt, thrives on outbound outreach, and knows that persistence wins deals. You are energized by building relationships, uncovering opportunities, and turning cold conversations into meaningful business discussions.&lt;/p&gt;
&lt;p&gt;This role is designed for someone with strong sales instincts who wants to develop into a full-cycle dealmaker. You will focus on identifying viable sites, engaging property owners and brokers, qualifying opportunities, and advancing conversations that ultimately lead to signed agreements. As you build experience and demonstrate sound judgment, you will take on increasing responsibility in negotiations and transaction management.&lt;/p&gt;
&lt;p&gt;We are less concerned with prior real estate experience than we are with your ability to generate opportunities, build trust, navigate objections, and consistently drive results.&lt;/p&gt;
&lt;p&gt;This position will support network expansion across the Southeast region and may require occasional domestic travel.&lt;/p&gt;
&lt;h3 class=&quot;content&quot;&gt;What You&#39;ll Do&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Build and Maintain the Pipeline&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Identify and research prospective sites that meet expansion criteria across priority markets.&lt;/li&gt;
&lt;li&gt;Develop target lists of property owners, landlords, brokers, developers, and other stakeholders.&lt;/li&gt;
&lt;li&gt;Continuously source new opportunities to ensure healthy pipeline coverage.&lt;/li&gt;
&lt;li&gt;Use CRM tools and market research resources to organize and prioritize outreach efforts.&lt;/li&gt;
&lt;li&gt;Maintain accurate prospect, site, and pipeline data.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Execute High-Volume Outreach&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Conduct high-volume outbound outreach through calls, emails, LinkedIn, and other channels.&lt;/li&gt;
&lt;li&gt;Engage property owners, brokers, and decision-makers to introduce opportunities and assess interest.&lt;/li&gt;
&lt;li&gt;Build relationships with prospective site hosts and industry stakeholders.&lt;/li&gt;
&lt;li&gt;Maintain disciplined follow-up cadences and consistently re-engage prospects over extended sales cycles.&lt;/li&gt;
&lt;li&gt;Overcome objections and navigate complex stakeholder environments to keep opportunities moving.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Qualify and Advance Opportunities&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Gather preliminary information regarding site ownership, availability, access, utilities, and general feasibility.&lt;/li&gt;
&lt;li&gt;Conduct initial qualification against established site criteria.&lt;/li&gt;
&lt;li&gt;Prepare site summaries and opportunity briefs for internal review.&lt;/li&gt;
&lt;li&gt;Coordinate exploratory calls, meetings, and site visits with the Site Acquisition Manager.&lt;/li&gt;
&lt;li&gt;Support negotiations and transaction discussions, assuming greater responsibility over time as experience and performance warrant.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;Operate with Discipline and Ownership&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Maintain a clean, organized pipeline with accurate forecasting and next steps.&lt;/li&gt;
&lt;li&gt;Track outreach activity, conversion metrics, and opportunity progression.&lt;/li&gt;
&lt;li&gt;Surface risks, blockers, and recommendations to internal stakeholders.&lt;/li&gt;
&lt;li&gt;Contribute to improvements in sourcing strategies, outreach messaging, broker engagement, and acquisition playbooks.&lt;/li&gt;
&lt;li&gt;Demonstrate ownership of outcomes rather than simply activity.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What Success Looks Like&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Consistently generating qualified site opportunities in priority markets.&lt;/li&gt;
&lt;li&gt;High outbound activity levels paired with strong conversion rates.&lt;/li&gt;
&lt;li&gt;Effective relationship development with property owners, brokers, and site hosts.&lt;/li&gt;
&lt;li&gt;Reliable advancement of opportunities from initial outreach through qualification.&lt;/li&gt;
&lt;li&gt;Increasing ability to independently manage negotiations and transaction discussions.&lt;/li&gt;
&lt;li&gt;Healthy pipeline coverage that supports long-term expansion goals.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 class=&quot;section-wrapper page-full-width&quot;&gt;What You&#39;ll Bring&amp;nbsp;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;1–5 years of experience in sales, business development, account management, recruiting, fundraising, market development, or another relationship-driven role.&lt;/li&gt;
&lt;li&gt;Proven success generating opportunities through cold outreach and persistent follow-up.&lt;/li&gt;
&lt;li&gt;Strong communication, persuasion, and relationship-building skills.&lt;/li&gt;
&lt;li&gt;Ability to handle rejection, remain resilient, and maintain consistent activity levels.&lt;/li&gt;
&lt;li&gt;Strong organizational skills and disciplined pipeline management habits.&lt;/li&gt;
&lt;li&gt;Self-motivated, competitive, and results-oriented.&lt;/li&gt;
&lt;li&gt;Interest in developing commercial negotiation and real estate transaction skills.&lt;/li&gt;
&lt;li&gt;Ability to travel occasionally within assigned markets.&lt;/li&gt;
&lt;li&gt;Authorized to work in the United States.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;Nice to Have&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Experience in commercial real estate, leasing, retail expansion, telecom, logistics, infrastructure, or related industries.&lt;/li&gt;
&lt;li&gt;Experience selling to business owners, property owners, or other sophisticated stakeholders.&lt;/li&gt;
&lt;li&gt;Familiarity with Salesforce or similar CRM platforms.&lt;/li&gt;
&lt;li&gt;Track record of exceeding sales, prospecting, or business development targets.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;This role is designed as a pathway into full-cycle site acquisition. High performers will have the opportunity to take on increasing responsibility for negotiations, transaction management, and deal ownership as they build experience and demonstrate success.&lt;/p&gt;
&lt;h3 class=&quot;content-wrapper posting-page&quot;&gt;What Else You Need to Know&amp;nbsp; &amp;nbsp;&lt;/h3&gt;
&lt;div&gt;
&lt;div&gt;Zipline is an equal opportunity employer and prohibits discrimination and harassment of any type without regard to race, color, ancestry, national origin, religion or religious creed, mental or physical disability, medical condition, genetic information, sex (including pregnancy, childbirth, and related medical conditions), sexual orientation, gender identity, gender expression, age, marital status, military or veteran status, citizenship, or other characteristics protected by state, federal or local law or our other policies.&lt;/div&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;
&lt;div&gt;We value diversity at Zipline and welcome applications from those who are traditionally underrepresented in tech. If you like the sound of this position but are not sure if you are the perfect fit, please apply!&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;

a16z-zipline:greenhouse:7779971003.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;h3&gt;About Zipline&lt;/h3&gt;
&lt;p&gt;Zipline is the world’s largest and most experienced drone delivery service. We are on a mission to serve all humans equally by ensuring access to food, medicine and essential goods anytime, anywhere. We design, build, and operate the world’s largest autonomous logistics system, delivering critical supplies quickly and reliably. Today, Zipline operates on four continents, makes a delivery somewhere in the world every 30 seconds, and has completed millions of deliveries to date, including blood, vaccines, medical supplies, food, and retail products.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Our customers include the world’s largest and most prominent healthcare systems, governments, retailers, restaurants and global businesses who rely on us to save lives, reduce emissions, increase economic opportunity, and provide delivery from point A to point B as fast as possible. The drone is only 15% of what we’ve built to enable seamless, reliable, global operations.&lt;/p&gt;
&lt;p&gt;Our system strengthens supply chains, reduces congestion, and gives people time back. With more than 140 million commercial autonomous miles safely flown, Zipline is redefining access to healthcare, consumer products, and food across the globe.&lt;/p&gt;
&lt;p&gt;We operate at a global scale and are looking for practical problem solvers who thrive on real-world challenges and rapid growth. Our team is motivated by building systems that have a direct, meaningful impact on people’s lives and by scaling the future of logistics. We are seeking people who sculpt from first principles, enjoy facing adversity, and can do the impossible at record breaking speeds.&lt;/p&gt;&lt;/div&gt;&lt;h2 data-path-to-node=&quot;8&quot;&gt;About the Emerging Talent Recruiting Team&lt;/h2&gt;
&lt;p data-path-to-node=&quot;9&quot;&gt;The Emerging Talent Recruiting Team is dedicated to finding, attracting, and hiring the next generation of builders, innovators, and leaders at Zipline. We manage the full lifecycle of our early-career programs, ensuring that Zipline is the premier destination for emerging talent across hardware, software and operations teams, amongst others. Our team designs impactful experiences that bridge the gap between academic brilliance and real-world autonomous logistics.&lt;/p&gt;
&lt;h2 data-path-to-node=&quot;2&quot;&gt;The Role&lt;/h2&gt;
&lt;p data-path-to-node=&quot;3&quot;&gt;We are looking for an Emerging Talent Recruiter to join us as a contractor to support our upcoming busy fall university recruiting season, with the potential for extension beyond that. In this role, you will play a key part in discovering and hiring the next generation of builders at Zipline. You will manage full-cycle recruiting for various early-career roles, while also planning and facilitating engaging recruiting events at universities and technical competitions. This is a hands-on, fast-paced contract position perfect for someone who excels at candidate engagement, event logistics, and building strong, collaborative partnerships with hiring managers during our peak hiring season.&lt;/p&gt;
&lt;h2 data-path-to-node=&quot;12&quot;&gt;What You&#39;ll Do&lt;/h2&gt;
&lt;ul data-path-to-node=&quot;13&quot;&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;13,0,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,0,0&quot; data-index-in-node=&quot;0&quot;&gt;Full-Cycle Recruiting:&lt;/strong&gt; Manage the end-to-end recruitment process for various internship roles, ensuring an efficient, high-touch, and inclusive experience for every candidate.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;13,1,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,1,0&quot; data-index-in-node=&quot;0&quot;&gt;Event Planning &amp;amp; Execution:&lt;/strong&gt; Strategize, plan, and facilitate engaging university events, tech talks, hackathons, and competition sponsorships that elevate Zipline’s brand visibility.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;13,2,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Stakeholder &amp;amp; Manager Management:&lt;/strong&gt; Build trusted partnerships with hiring managers and business leaders to align on hiring needs, define role requirements, and guide them through interview loops and candidate selection.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;13,3,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,3,0&quot; data-index-in-node=&quot;0&quot;&gt;On-Campus &amp;amp; Event Representation:&lt;/strong&gt; Travel to universities and key industry competitions to engage directly with students, pitch Zipline&#39;s mission, and proactively source top-tier talent.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;13,5,0&quot;&gt;&lt;strong data-path-to-node=&quot;13,5,0&quot; data-index-in-node=&quot;0&quot;&gt;Data &amp;amp; Pipeline Tracking:&lt;/strong&gt; Keep recruiting data clean and up-to-date in our ATS (Applicant Tracking System), providing regular updates on pipeline health and event ROI to recruiting leadership.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2 data-path-to-node=&quot;14&quot;&gt;What You&#39;ll Bring&lt;/h2&gt;
&lt;ul data-path-to-node=&quot;15&quot;&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;15,0,0&quot;&gt;&lt;strong data-path-to-node=&quot;15,0,0&quot; data-index-in-node=&quot;0&quot;&gt;Early Career Expertise:&lt;/strong&gt; 3+ years of experience dedicated to university, early career, or emerging talent recruiting, preferably within a fast-paced tech or engineering environment.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;15,1,0&quot;&gt;&lt;strong data-path-to-node=&quot;15,1,0&quot; data-index-in-node=&quot;0&quot;&gt;Event Management Savvy:&lt;/strong&gt; Demonstrated experience planning, organizing, and executing creative on-campus or virtual recruiting events and managing logistics seamlessly.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;15,2,0&quot;&gt;&lt;strong data-path-to-node=&quot;15,2,0&quot; data-index-in-node=&quot;0&quot;&gt;Strong Stakeholder Management:&lt;/strong&gt; Excellent communication and interpersonal skills, with a proven ability to influence, guide, and build strong relationships with hiring managers and cross-functional teams.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;15,3,0&quot;&gt;&lt;strong data-path-to-node=&quot;15,3,0&quot; data-index-in-node=&quot;0&quot;&gt;Willingness to Travel:&lt;/strong&gt; Ability and excitement to travel domestically (primarily during peak university recruiting seasons) to attend career fairs, competitions, and campus events.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;15,4,0&quot;&gt;&lt;strong data-path-to-node=&quot;15,4,0&quot; data-index-in-node=&quot;0&quot;&gt;Candidate-Centric Mindset:&lt;/strong&gt; A passion for delivering an empathetic, transparent, and stellar experience to early-career candidates navigating the job market.&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p data-path-to-node=&quot;15,5,0&quot;&gt;&lt;strong data-path-to-node=&quot;15,5,0&quot; data-index-in-node=&quot;0&quot;&gt;Execution Focus:&lt;/strong&gt; Exceptional organizational skills with the ability to manage multiple high-volume pipelines and moving event timelines simultaneously.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3 data-path-to-node=&quot;16&quot;&gt;What Else You Should Know&lt;/h3&gt;
&lt;p id=&quot;p-rc_e602f428b90e9496-41&quot; data-path-to-node=&quot;17&quot;&gt;&lt;span data-path-to-node=&quot;17,0&quot;&gt;Zipline is unable to sponsor work visas for applicants to this position.&lt;/span&gt;&lt;/p&gt;
&lt;p id=&quot;p-rc_e602f428b90e9496-42&quot; data-path-to-node=&quot;18&quot;&gt;&lt;span data-path-to-node=&quot;18,0&quot;&gt;The starting cash range for this co&lt;span class=&quot;citation-479 citation-end-479&quot;&gt;ntractor position is $60.00 - $65.00 / hour. Please note that this is a target, starting cash range for a candidate who meets the minimum qualifications for this role. The final cash pay for this role will depend on a variety of factors, including a specific can&lt;/span&gt;didate&#39;s experience, qualifications, skills, and working location.&lt;/span&gt;&lt;/p&gt;
&lt;p id=&quot;p-rc_e602f428b90e9496-43&quot; data-path-to-node=&quot;19&quot;&gt;&lt;span data-path-to-node=&quot;19,0&quot;&gt;Zipline is an equal opportunity employer and prohibits discrimination and harassment of any type without regard to race, color, religion, age, sex, national origin, disability status, genetics, protected veteran status, sexual orientation, gender identity or expression, or any other characteristic protected by federal, state or local laws or our own sensibilities.&lt;/span&gt;&amp;nbsp;&lt;/p&gt;
&lt;p id=&quot;p-rc_e602f428b90e9496-45&quot; data-path-to-node=&quot;21&quot;&gt;&lt;span data-path-to-node=&quot;21,0&quot;&gt;&lt;span class=&quot;citation-477 citation-end-477&quot;&gt;Zipline is also committed to providing reasonable accommodations to individuals with disabilities. Please let your point of contact at&lt;/span&gt; Zipline know if you require any accommodations throughout your interview process.&lt;/span&gt;&lt;/p&gt;

abstractvc-newlimit:greenhouse:596988600.descriptionHtml:
&lt;h2&gt;About NewLimit&lt;/h2&gt;
&lt;p&gt;NewLimit is seeking a Scientist or Senior Scientist with deep expertise in molecular biology, pharmacokinetics and translational biomarker assay development. In this role, you will lead the design, development, and qualification of pharmacokinetic (PK) and pharmacodynamic (PD) assays that characterize the biodistribution and biological activity of our mRNA-LNP medicines in preclinical and IND enabling studies. You will serve as a technical leader within our bioanalytical function, shaping biomarker assay strategy and partnering cross-functionally to advance our therapeutic programs toward IND-enabling milestones.&lt;/p&gt;
&lt;h2&gt;&lt;strong&gt;What you’ll do&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Own the end-to-end design, development, and qualification of PK and PD biomarker assays across various platforms to support preclinical and IND-enabling studies&lt;/li&gt;
&lt;li&gt;Discover and validate pharmacodynamic biomarkers to support the clinical development of drugs across multiple programs&lt;/li&gt;
&lt;li&gt;Drive data analysis, interpretation, and reporting for bioanalytical studies to support program decision-making with audit-ready data packages&lt;/li&gt;
&lt;li&gt;Contribute to sample processing workflows including tissue harvesting, primary cell culture, and complex matrix handling&lt;/li&gt;
&lt;li&gt;Mentor research associates, establish SOPs, and build institutional knowledge within the bioanalytical function&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Requirements&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;PhD in molecular biology, biochemistry, cell biology, or a related field or equivalent industry experience (5+ years)&lt;/li&gt;
&lt;li&gt;3+ years of hands-on experience in various quantitative bioanalytical assay platforms (e.g., RT-qPCR, ddPCR, ELISA, MSD, Olink, SOMAscan, NGS-based methods) in complex biological matrices (serum, plasma, tissue homogenates)&lt;/li&gt;
&lt;li&gt;Strong working knowledge of bioanalytical method qualification/validation principles for PK/PD biomarker measurements, including familiarity with ICH M10 guidelines and fit-for-purpose frameworks&lt;/li&gt;
&lt;li&gt;History of delivering results for bioanalytical projects -- you&#39;ve discovered a PD biomarker or built an assay and solved all the problems along the way&lt;/li&gt;
&lt;li&gt;Experience with primary cell culture and tissue-derived sample workflows&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Nice to have&lt;/strong&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;Track record of bioanalytical method transfer and CRO management for outsourced projects&lt;/li&gt;
&lt;li&gt;Familiarity with preclinical drug development timelines and regulatory submissions (IND, TGA, CTD format)&lt;/li&gt;
&lt;li&gt;Experience with mRNA-LNP biodistribution or nucleic acid–based PK assays&lt;/li&gt;
&lt;li&gt;Experience developing products in emerging therapeutic modalities (gene therapy, nucleic acid therapies, cell therapy)&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;Benefits&lt;/h2&gt;
&lt;p&gt;NewLimit provides generous benefits so our team can remain focused on our mission:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Comprehensive Health, Dental, and Vision insurance&lt;/li&gt;
&lt;li&gt;401(k) plan with company match&lt;/li&gt;
&lt;li&gt;Paid parental leave&lt;/li&gt;
&lt;li&gt;Industry-leading PTO: 20 days per year plus holidays&lt;/li&gt;
&lt;li&gt;On-site meals and snacks&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Salary Range: $130,000 to $160,000. Compensation for the role will depend on a number of factors, including a candidate’s qualifications, skills, competencies, and experience. NewLimit offers a competitive benefits package, which includes a 401k, healthcare coverage, and 20 days of PTO. Learn more at: &lt;a href=&quot;https://www.newlimit.com/careers&quot;&gt;https://www.newlimit.com/careers&lt;/a&gt; &amp;nbsp; *This compensation and benefits information is based on Company&#39;s good faith estimate as of the date of publication and may be modified in the future.&lt;/p&gt;

adventinternational-definitive-healthcar.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;About &lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;Definitive Healthcare&lt;/span&gt;&lt;span data-ccp-parastyle=&quot;heading 1&quot;&gt;:&lt;/span&gt;&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;134245418&amp;quot;:true,&amp;quot;134245529&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335559685&amp;quot;:0,&amp;quot;335559737&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;At Definitive Healthcare (NASDAQ: DH), we’re passionate about turning data, analytics, and expertise into meaningful intelligence that helps our customers achieve success and shape the future of healthcare. We empower them to uncover the right markets, opportunities, and people—paving the way for smarter decisions and greater impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&lt;span data-teams=&quot;true&quot;&gt;Headquartered just outside of Boston, Massachusetts, Definitive Healthcare operates across North America, Europe, and India, supporting a growing global client base of more than 2,400 customers since our founding in 2011.&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We’re also a great place to work. &lt;/span&gt;In 2024 and 2025, we earned multiple workplace honors, including Built In’s 100 Best Places to Work in Boston (both years), a Stevie Bronze Award for Great Employers, and recognition as a Great Place to Work in India.&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We foster a collaborative, inclusive culture where diverse perspectives drive innovation. Through programs like DefinitiveCares and our employee-led affinity groups we strive to promote connection, education, and inclusion.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;335551550&amp;quot;:0,&amp;quot;335551620&amp;quot;:0,&amp;quot;335559738&amp;quot;:240,&amp;quot;335559739&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;We are looking for a &lt;/span&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Data Scientist&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;to help shape the next generation of analytics that power our products. This role is ideal for someone who thrives at the intersection of data science, product innovation, and healthcare commercialization.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the Role&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;As a Data Scientist, you will design, develop, and operationalize advanced analytics that enhance the value of Definitive Healthcare’s proprietary datasets. You’ll lead strategic product initiatives, build scalable models, and translate complex data into actionable insights that support our clients’ commercial strategy goals.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;You will guide analytic frameworks and collaborate closely with product, engineering, and subject matter experts to bring new capabilities to market.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;What&amp;nbsp;You’ll&amp;nbsp;Do&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
