&lt;h3 style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot;&gt;&lt;span class=&quot;ui-provider wf b c d e f g h i j k l m n o p q r s t u v w x y z ab ac ae af ag ah ai aj ak&quot;&gt;&lt;span style=&quot;color: rgb(0, 0, 0);&quot;&gt;&lt;span class=&quot;EOP Selected SCXW78692936 BCX8&quot; data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:256}&quot;&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;ol&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;担当プログラムにおける&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;CMC&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;薬事戦略の立案及び実行に貢献し、関連する薬事業務の日常的な推進を主導します。グローバルおよび地域チームと連携し、製品パイプラインのプロジェクト計画およびタイムラインを策定・維持するとともに、グローバルの薬事&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;申請の調整および実務的な支援を行います。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Clinical Trial&amp;nbsp;Notifications（CTN&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;）、新薬承認申請（&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;NDA）、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;承認事項一部変更承認申請&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;（PCA）、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;軽微変更届&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;（MCN&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;）などに関する報告要件およびその他のコミットメントがすべて満たされるよう、他のメンバーに対して機能的な指導・管理を行い、指導・管理を行い、必要に応じて課題やリスクを&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Head of Regulatory Affairs Japan&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;及び／あるいは&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;VP,&amp;nbsp;Global Regulatory CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;にエスカレーションします&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Ultragenyx&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;の製品パイプラインに関するグローバル薬事コンプライアンスについて、助言および実務的な支援を提供し、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;関連の変更管理の評価、プロセスおよび製品の同等性に関する戦略的評価、それらの規制上の影響評価および対応の実行支援を行います&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;。&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;重要なリスクや課題については、適切に&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;Head of Regulatory Affairs Japan&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;及び／あるいは&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;VP,&amp;nbsp;Global Regulatory CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;へエスカレーションします。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;規制当局への申請に必要な&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;関連文書の作成、レビューおよび提出を調整し、地域の規制当局との対応を実務的に支援します。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;地域の規制要件および企業目標を満たすため、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;関連の薬事申請文書が適切な品質を確保し、合意された期限内に準備されるよう、管理調整を行います。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;薬事コミットメントおよび当局への報告義務の状況を追跡・監視するための集中した文書管理を維持・管理するとともに&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;定められたプロセスに従い、状況報告やその他の情報を作成・発信し、関連組織に共有します。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;製剤開発、品質保証（&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;QA&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;）、品質管理（&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;QC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;）、製造、外部委託機関やコンサルタントなど、グローバルおよび各機能横断チームに対し、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;薬事に関する戦略的かつ技術的なサポート、指針および専門知識を提供し、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;領域における&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Regulatory Affairs Japan&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;の窓口として対応します。また、グローバル薬事戦略に整合し、&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Head of Regulatory Affairs Japan&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;及び／あるいは&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;VP, Global Regulatory CMC&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;のガイダンスのもと、適用される規制要件や選択肢、および関連リスクを十分に考慮したうえで開発プログラムに適切に反映し、製品が適切な規制やガイドラインに準拠して開発・製造されるよう確保します。&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;line-height: 2;&quot;&gt;&lt;span data-contrast=&quot;auto&quot;&gt;CMC&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;の規制環境に関して指針や助言を提供し、新しい規制や要件の変更が与える影響を評価します。&lt;/span&gt;&lt;/li&gt;
&lt;/ol&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&lt;/span&gt;&lt;/p&gt;
&lt;h3 style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Requirements:&lt;/strong&gt;&lt;/h3&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&lt;/span&gt;&lt;/p&gt;
