&lt;h3 style=&quot;line-height: 1;&quot;&gt;&lt;span style=&quot;font-family: helvetica, arial, sans-serif;&quot;&gt;&lt;strong&gt;Primary Responsibilities&lt;/strong&gt;&lt;/span&gt;&lt;/h3&gt;
