&lt;p&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:2,&amp;quot;335551620&amp;quot;:2,&amp;quot;335559739&amp;quot;:240,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Priority Application Deadline: Tuesday, 6/09/2026&lt;/span&gt;&lt;/strong&gt;&lt;strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;at 11:59pm ET&lt;/span&gt;&lt;/em&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:2,&amp;quot;335551620&amp;quot;:2,&amp;quot;335559739&amp;quot;:160,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;About JFF&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;For more than 40 years, JFF has been uniquely positioned at the intersection of education and workforce. We design and scale innovative solutions, influence&amp;nbsp;policy&amp;nbsp;and practice, and build powerful partnerships so that learners and workers have the skills, resources, and credentials they need to thrive in a rapidly changing economy. Together with our partners, we work to improve labor market outcomes for youth and adults who face systemic barriers to economic mobility.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;JFF operates at the national, state, and local levels, helping to connect education, workforce, and economic development within regions of all sizes. Our staff are based across the United States, working primarily remotely with offices in Boston (headquarters), Washington, DC, and Oakland, CA. Our work is powered by a broad network of partners and funders across the public, private, and nonprofit sectors, all committed to advancing economic opportunity.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;If&amp;nbsp;you’re&amp;nbsp;inspired by the chance to drive real systems change, we invite you to&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.jff.org/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;learn more about JFF&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;&amp;nbsp;and explore our current career opportunities at&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://www.jff.org/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;jff.org&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;auto&quot;&gt;. Join us as we build a future that works for everyone.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;Equal Employment Opportunity at JFF&lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;Inclusion, belonging, and well-being are core to JFF’s&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://archive.jff.org/points-of-view/our-north-star-quality-jobs-75-million-people/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;North Star&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;and mission. We aim to cultivate a culture that centers the overall care, well-being, and success of the employee through flexible work hours, balanced workloads, professional development, and career advancement opportunities for all.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;JFF is a fair chance employer and in alignment to our&amp;nbsp;&lt;/span&gt;&lt;a href=&quot;https://archive.jff.org/points-of-view/our-north-star-quality-jobs-75-million-people/&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;&lt;span data-ccp-charstyle=&quot;Hyperlink&quot;&gt;North Star&lt;/span&gt;&lt;/span&gt;&lt;/a&gt;&lt;span data-contrast=&quot;none&quot;&gt;, we hire based on qualifications, experience, and are committed to fair opportunity for all qualified candidates – including those without a 4-year degree or formally incarnated individuals.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:false,&amp;quot;134233118&amp;quot;:false,&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:1,&amp;quot;335551620&amp;quot;:1,&amp;quot;335557856&amp;quot;:16777215,&amp;quot;335559738&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;About the Position:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Reporting to the Accounting Manager, and as a member of&lt;/span&gt;&lt;span data-contrast=&quot;none&quot;&gt;&amp;nbsp;the&amp;nbsp;accounting&amp;nbsp;team, the Senior Accountant will meticulously manage a&amp;nbsp;&lt;/span&gt;&lt;span data-contrast=&quot;auto&quot;&gt;multitude of accounting activities including&amp;nbsp;bi-weekly payroll review&amp;nbsp;and&amp;nbsp;payroll&amp;nbsp;allocation, general&amp;nbsp;ledger&amp;nbsp;reconciliations,&amp;nbsp;bank reconciliations,&amp;nbsp;revenue recognition, cost allocations&amp;nbsp;and&amp;nbsp;reclasses, month-end close and year-end audit preparation.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;This position presents an exciting&amp;nbsp;opportunity for an accounting professional to broaden their&amp;nbsp;expertise&amp;nbsp;across all&amp;nbsp;facets&amp;nbsp;of finance within a&amp;nbsp;mission-driven organization.&amp;nbsp;This person will play a key role in supporting elements around&amp;nbsp;numerous&amp;nbsp;accounting functions,&amp;nbsp;and&amp;nbsp;partner&amp;nbsp;cross functionally across the entire Finance team to ensure best practices&amp;nbsp;to support the audit and month end components for the team.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;none&quot;&gt;The&amp;nbsp;ideal&amp;nbsp;candidate for this role is a dynamic individual who has experience with&amp;nbsp;bank&amp;nbsp;account&amp;nbsp;reconciliation,&amp;nbsp;general ledger&amp;nbsp;account&amp;nbsp;reconciliation, cost&amp;nbsp;allocation&amp;nbsp;to support&amp;nbsp;different&amp;nbsp;accounting functions,&amp;nbsp;including&amp;nbsp;payroll processing and allocation.&amp;nbsp;This&amp;nbsp;is&amp;nbsp;a great opportunity&amp;nbsp;for an individual who thrives in an environment of change, approaches tasks with unwavering attention to detail, and exemplifies a strong customer service around financial and stakeholder engagement.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;What&amp;nbsp;you&#39;ll&amp;nbsp;do: &lt;/span&gt;&lt;/strong&gt;&lt;span data-contrast=&quot;none&quot;&gt; &lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559738&amp;quot;:60,&amp;quot;335559739&amp;quot;:120,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Manage&amp;nbsp;daily&amp;nbsp;accounting functions and&amp;nbsp;support key pieces of&amp;nbsp;the monthly and annual close&lt;/span&gt;&lt;/em&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Conduct thorough reviews of bi-weekly payroll and serve as a backup for payroll processing in collaboration with the&amp;nbsp;accounting team&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Provide support in the&amp;nbsp;collection, validation, and consolidation of payroll input data in preparation for bi-weekly payroll processing&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Manage&amp;nbsp;and support the&amp;nbsp;reconciliation&amp;nbsp;of multiple&amp;nbsp;bank and&amp;nbsp;investment&amp;nbsp;accounts&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Process&amp;nbsp;bi-weekly&amp;nbsp;payroll&amp;nbsp;allocation&amp;nbsp;entries&amp;nbsp;and&amp;nbsp;accruals,&amp;nbsp;prepare reconciliation for balance sheet accounts and audit schedules&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Monitor and ensure compliance with&amp;nbsp;internal financial and accounting controls over procurement, payroll, receipts, disbursements, and other processes&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Maintain the&amp;nbsp;fixed&amp;nbsp;asset and associated depreciation schedules&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prepare&amp;nbsp;monthly journal&amp;nbsp;entries&amp;nbsp;and&amp;nbsp;ensure proper recording&amp;nbsp;and tracking&amp;nbsp;of new purchases and disposals&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prepare&amp;nbsp;journal entries and collecting, analyzing, and summarizing account information for monthly and year-end closing&amp;nbsp;including prepaid entries, accruals, reclasses and others&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Manage&amp;nbsp;and&amp;nbsp;maintain&amp;nbsp;lease&amp;nbsp;schedules ensuring proper amortization of right of&amp;nbsp;use&amp;nbsp;assets&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Perform indirect cost recovery and process&amp;nbsp;other cost&amp;nbsp;allocations across&amp;nbsp;the organization&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Prepare the&amp;nbsp;federal drawdowns, reconciling federal revenue and&amp;nbsp;expenses and&amp;nbsp;assisting&amp;nbsp;in preparation of&amp;nbsp;SEFA (Schedule of Expenditures for Federal Awards)&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Manage&amp;nbsp;state registrations and&amp;nbsp;other organization fillings&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Collaborate&amp;nbsp;with&amp;nbsp;key stakeholders across the&amp;nbsp;Finance&amp;nbsp;team to support&amp;nbsp;team&amp;nbsp;goals and&amp;nbsp;objectives&lt;/span&gt;&lt;/em&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Respond to inquiries from&amp;nbsp;finance&amp;nbsp;leadership,&amp;nbsp;finance&amp;nbsp;colleagues&amp;nbsp;and&amp;nbsp;other program managers&amp;nbsp;regarding&amp;nbsp;financial results,&amp;nbsp;and&amp;nbsp;special reporting requests&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Assist&amp;nbsp;with preparation of financial reporting to donors and other statutory financial reports&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Assist&amp;nbsp;with annual audit&amp;nbsp;requests,&amp;nbsp;resource-gathering, and recommended follow-through&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Provide accounting support&amp;nbsp;and collaborate closely with grants stewards team&amp;nbsp;and finance business&amp;nbsp;partner&amp;nbsp;on&amp;nbsp;grants&amp;nbsp;reports and analysis&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li&gt;&lt;span data-contrast=&quot;none&quot;&gt;Partner with grants steward&amp;nbsp;team&amp;nbsp;to&amp;nbsp;review and prepare reclassification entries&amp;nbsp;to ensure proper reporting of expenses to individual awards&amp;nbsp;ensuring proper documentation is received&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;&lt;em&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Analyze&amp;nbsp;and implement&amp;nbsp;best practices around&amp;nbsp;efficient procedures and&amp;nbsp;resources&amp;nbsp;across&amp;nbsp;the Finance team&lt;/span&gt;&lt;/em&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335559739&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
